package store.model;
public final class Product{private final String id,name;private final double unitPrice;private final Category category;private boolean active=true;private int stock;public Product(String id,String name,double price,Category category){if(id==null||name==null||price<0||category==null)throw new IllegalArgumentException("Invalid product");this.id=id;this.name=name;unitPrice=price;this.category=category;}public String id(){return id;}public String name(){return name;}public double unitPrice(){return unitPrice;}public Category category(){return category;}public boolean active(){return active;}public int stock(){return stock;}public void activate(){active=true;}public void deactivate(){active=false;}public void increaseStock(int q){if(q<=0)throw new IllegalArgumentException("Quantity must be positive");stock+=q;}public void decreaseStock(int q){if(q<=0||q>stock)throw new IllegalArgumentException("Insufficient stock or invalid quantity");stock-=q;}}
